'use client';
import { useState } from 'react';
import Sidebar from '@/components/sidebar/page';
import Header from '@/components/header/page';
import Footer from '@/components/footer/page';
import Keymetrics from '@/components/content/keymetrics';
import Revenueupdate from '@/components/content/revenueupdate';
import Saleoverview from '@/components/content/saleoverview';
import OrdersOverview from '@/components/content/ordersoverview';
import WeeklyPerformance from '@/components/content/weeklyperformance';
import ProfitLossSummary from '@/components/content/profit-loss-summary';
import StockAlerts from '@/components/content/stockalerts';
import CustomerFeedback from '@/components/content/customerfeedback';
import PaginationComponent from '@/components/pagination/page';

const components = [
  { Component: Revenueupdate, key: 'revenueupdate' },
  { Component: Keymetrics, key: 'keymetrics' },
  { Component: Saleoverview, key: 'saleoverview' },
  { Component: OrdersOverview, key: 'ordersoverview' },
  { Component: StockAlerts, key: 'stockalerts' },
  { Component: WeeklyPerformance, key: 'weeklyperformance' },
  { Component: ProfitLossSummary, key: 'profitlosssummary' },
  { Component: CustomerFeedback, key: 'customerfeedback' }
];

export default function ProductPerformancePage() {
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 4;

  const totalPages = Math.ceil(components.length / itemsPerPage);

  const handlePageChange = (_event: React.ChangeEvent<unknown>, page: number) => {
    setCurrentPage(page);
  };

  const startIndex = (currentPage - 1) * itemsPerPage;
  const currentComponents = components.slice(startIndex, startIndex + itemsPerPage);

  return (
    <div className="flex flex-col min-h-screen bg-gradient-to-br from-white via-gray-50 to-gray-100 text-gray-900">
      {/* Sidebar and Main Layout */}
      <div className="flex flex-grow">
        {/* Sidebar */}
        <Sidebar />

        {/* Main Content */}
        <div className="flex flex-col flex-grow">
          {/* Header */}
          <Header />

          {/* Page Content */}
          <main className="container flex-grow mx-auto px-6 py-10">
            {/* Page Title */}
            <header className="mb-6">
              <h1 className="text-3xl font-bold text-gray-800">Product Performance</h1>
              <p className="text-lg text-gray-600">Track and analyze the key metrics driving your product success.</p>
            </header>

            {/* Render paginated components */}
            <section className="mb-12">
              {currentComponents.map(({ Component, key }) => (
                <div key={key}>
                  <Component />
                </div>
              ))}
            </section>

            {/* Pagination */}
            <section className="mt-8">
              <PaginationComponent
                currentPage={currentPage}
                totalPages={totalPages}
                onPageChange={handlePageChange}
              />
            </section>
          </main>
        </div>
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
}
